import json
from collections import Counter
with open('fees.json') as f:
    fees=json.load(f)
print(len(fees))
print(fees[0])
for field in ['card_scheme','account_type','capture_delay','monthly_fraud_level','monthly_volume','is_credit','aci','intracountry']:
    vals=Counter()
    for r in fees:
        v=r.get(field)
        if isinstance(v, list):
            vals[tuple(v)]+=1
        else:
            vals[v]+=1
    print('---', field, len(vals))
    for k,v in vals.most_common(30):
        print('   ', k, v)
# mcc values
mccs=set()
for r in fees:
    m=r.get('merchant_category_code')
    if isinstance(m, list):
        mccs.update(m)
    elif m is not None:
        mccs.add(m)
print('mcc count', len(mccs), sorted(mccs)[:20], 5942 in mccs)

